import { SDKRequestToRESTRequestRenameMap } from './constants.js';
export const systemFieldRenameMap = SDKRequestToRESTRequestRenameMap;
export function renameFieldPathBySegment(fieldPath, renameMap) {
    return fieldPath
        ?.split('.')
        .map((segment) => renameMap?.[segment] ?? segment)
        .join('.');
}
export function renameSystemFieldPath(fieldPath, { transformSystemFields = true } = {}) {
    return transformSystemFields
        ? renameFieldPathBySegment(fieldPath, systemFieldRenameMap)
        : fieldPath;
}
const SORT_FIELD_NAME_PATH = 'sort.fieldName';
export function renameSortFieldNameValue(path, value, renameMap) {
    const isSortFieldName = path === SORT_FIELD_NAME_PATH || path.endsWith(`.${SORT_FIELD_NAME_PATH}`);
    return isSortFieldName && typeof value === 'string'
        ? renameFieldPathBySegment(value, renameMap)
        : value;
}
